import java.util.Scanner;

abstract class Shape {
    private final String name;

    Shape(String name) {
        this.name = name;
    }

    String getName() {
        return name;
    }

    abstract int area();
}

class Rect extends Shape {
    private int w;
    private int h;

    Rect(int w, int h) {
        super("四角形");
        this.w = w;
        this.h = h;
    }

    @Override
    int area() {
        return w * h;
    }
}

class Square extends Shape {
    private int s;

    Square(int s) {
        super("正方形");
        this.s = s;
    }

    @Override
    int area() {
        return s * s;
    }
}

class Triangle extends Shape {
    private int b;
    private int h;

    Triangle(int b, int h) {
        super("三角形");
        this.b = b;
        this.h = h;
    }

    @Override
    int area() {
        return b * h / 2;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        Shape[] shapes = new Shape[k];

        for (int i = 0; i < k; i++) {
            String type = sc.next();
            if (type.equals("S")) {
                int side = sc.nextInt();
                shapes[i] = new Square(side);
            } else {
                int a = sc.nextInt();
                int b = sc.nextInt();
                if (type.equals("R")) {
                    shapes[i] = new Rect(a, b);
                } else {
                    shapes[i] = new Triangle(a, b);
                }
            }
        }

        int total = 0;
        Shape biggest = shapes[0];

        for (Shape s : shapes) {
            System.out.println(s.getName() + " 面積 " + s.area());
            total += s.area();
            if (s.area() > biggest.area()) {
                biggest = s;
            }
        }

        System.out.println("合計 " + total);
        System.out.println("最大 " + biggest.getName());
    }
}
